# 5) Universal empty-space context menu: Add the current tab\'s primary record, and pin the current tab.
empty = '''import { useEffect, useMemo, useState } from "react";\nimport { useNavigate, useRouterState } from "@tanstack/react-router";\nimport { Plus, Pin } from "lucide-react";\nimport { useProjectStore } from "@/store/project-store";\nimport { useSession } from "@/store/session-store";\nimport { NAV, navLabel } from "@/lib/nav";\nimport { togglePin } from "@/lib/pins";\nimport { runQuickAction, type QuickActionId } from "@/lib/quick-actions";\n\ntype AddSpec = { label: string; quick?: QuickActionId; patterns: RegExp[] };\nconst ADD_BY_PATH: Record<string, AddSpec> = {\n  "/app/medicines": { label: "Add medicine", quick: "new-medicine", patterns: [/add\\s+medicine/i,/new\\s+medicine/i] },\n  "/app/purchases": { label: "New purchase", quick: "new-purchase", patterns: [/new\\s+purchase/i,/add\\s+purchase/i] },\n  "/app/customers": { label: "Add customer", quick: "new-customer", patterns: [/add\\s+customer/i,/new\\s+customer/i] },\n  "/app/suppliers": { label: "Add supplier", quick: "new-supplier", patterns: [/add\\s+supplier/i,/new\\s+supplier/i] },\n  "/app/categories": { label: "Add category", patterns: [/add\\s+categor/i,/new\\s+categor/i] },\n  "/app/racks": { label: "Add rack", patterns: [/add\\s+rack/i,/new\\s+rack/i] },\n  "/app/prescriptions": { label: "Add prescription", patterns: [/add\\s+prescription/i,/new\\s+prescription/i] },\n  "/app/stocktake": { label: "New stock take", patterns: [/new\\s+stock\\s+take/i,/start\\s+stock\\s+take/i,/add\\s+stock\\s+take/i] },\n  "/app/messages": { label: "New message", patterns: [/new\\s+message/i,/send\\s+message/i] },\n};\n\nfunction isInteractive(target: EventTarget | null) {\n  const el = target instanceof HTMLElement ? target : null;\n  return !!el?.closest('button,a,input,textarea,select,[role="button"],[role="tab"],[role="menu"],[role="dialog"]');\n}\n\nexport function EmptySpaceMenu() {\n  const pathname = useRouterState({ select: s => s.location.pathname });\n  const navigate = useNavigate();\n  const data = useProjectStore(s => s.data);\n  const user = useSession(s => s.user);\n  const [open, setOpen] = useState(false);\n  const [point, setPoint] = useState({ x: 0, y: 0 });\n  useEffect(() => {\n    const main = document.querySelector("main");\n    if (!main) return;\n    const onContext = (e: MouseEvent) => {\n      if (isInteractive(e.target)) return;\n      e.preventDefault();\n      setPoint({ x: e.clientX, y: e.clientY });\n      setOpen(true);\n    };\n    const close = () => setOpen(false);\n    main.addEventListener("contextmenu", onContext);\n    window.addEventListener("click", close);\n    window.addEventListener("resize", close);\n    return () => { main.removeEventListener("contextmenu", onContext); window.removeEventListener("click", close); window.removeEventListener("resize", close); };\n  }, [pathname]);\n  const item = NAV.find(n => n.to === pathname);\n  const label = item ? navLabel(item, data?.settings) : pathname;\n  const add = ADD_BY_PATH[pathname];\n  const canPin = !!user && (user.role === "admin" || user.permissions.pinPanel === true);\n  const left = Math.min(point.x, Math.max(8, window.innerWidth - 240));\n  const top = Math.min(point.y, Math.max(8, window.innerHeight - 120));\n  if (!open || !data || !item) return null;\n  const triggerAdd = () => {\n    setOpen(false);\n    if (add?.quick) { runQuickAction(add.quick, navigate); return; }\n    const buttons = Array.from(document.querySelectorAll<HTMLElement>("main button")).filter(b => { const text = (b.textContent || "").replace(/\\s+/g," ").trim(); return add?.patterns.some(r => r.test(text)); });\n    if (buttons[0]) { buttons[0].click(); return; }\n    if (pathname === "/app/messages") navigate({ to: pathname });\n  };\n  const pin = () => { setOpen(false); togglePin({ id: pathname, label, kind: "nav", to: pathname }); };\n  return <div className="fixed inset-0 z-[10000] pointer-events-none">\n    <div className="pointer-events-auto absolute min-w-52 rounded-md border bg-popover p-1 text-popover-foreground shadow-elevated" style={{left,top}} onClick={e=>e.stopPropagation()}>\n      <div className="px-2 py-1 text-[11px] uppercase tracking-widest text-muted-foreground">{label}</div>\n      {add && <button className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-sm hover:bg-accent" onClick={triggerAdd}><Plus className="h-4 w-4" />{add.label}</button>}\n      {canPin && <button className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-sm hover:bg-accent" onClick={pin}><Pin className="h-4 w-4" />Pin current tab</button>}\n      {!add && !canPin && <p className="px-2 py-1.5 text-xs text-muted-foreground">No quick action available here.</p>}\n    </div>\n  </div>;\n}\n'''
